INSERT INTO v2_array_dwd_rebuild_20261123.dwd_stock_main_business WITH version_flags AS (SELECT *,max(toUInt8(_observation_versions>1)) OVER (PARTITION BY `ts_code`,`end_date`,`bz_code`,`bz_item`,`curr_type`) AS _key_conflict FROM (SELECT *,uniqExact(source_record_hash) OVER (PARTITION BY `ts_code`,`end_date`,`bz_code`,`bz_item`,`curr_type`,sys_from) AS _observation_versions FROM v2_array_dwd_rebuild_20261123.dwd_stock_main_business_unresolved)) SELECT `ts_code`,`end_date`,`bz_item`,`bz_code`,`bz_sales`,`bz_profit`,`bz_cost`,`curr_type`,`update_flag`,`instrument_id`,`instrument_type`,`exchange`,`source_code`,`event_date`,`available_trade_date`,`sys_from`,`sys_to`,`source`,`source_table`,`source_batch_id`,`source_record_hash`,`availability_basis` FROM version_flags WHERE _key_conflict=0